CREATE TABLE `artist_packages` (
  `Id` char(36) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL,
  `Title` varchar(100) NOT NULL,
  `DurationMinutes` int(11) NOT NULL,
  `BasePrice` decimal(18,2) NOT NULL,
  `Description` varchar(1000) NOT NULL,
  `UserId` char(36) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Despejando dados para a tabela `artist_packages`
--

INSERT INTO `artist_packages` (`Id`, `Title`, `DurationMinutes`, `BasePrice`, `Description`, `UserId`) VALUES
('1ef39ff1-2a48-4cb4-893d-f573ebfa5c03', 'Show Oficial Pocket Acústico', 120, 1200.00, 'Formato reduzido ideal para bares e eventos corporativos de pequeno porte.', 'dd1fc02e-741c-42f6-8d63-764e8067d8c9'),
('276abb96-3910-42cb-a7eb-cbec1a77b188', 'Show Oficial Pocket Acústico', 90, 1200.00, 'Formato reduzido ideal para bares e eventos corporativos de pequeno porte.', '143a8824-6fd8-45a7-9aaa-9c9003549a9c'),
('3f8dfed3-22b9-44d3-a83b-fd67ba7412e2', 'Pocket Show', 130, 600.00, 'Ideal para eventos intimistas, casamentos menores, jantares ou recepções.Formato: Dupla + 1 instrumentista (violão/violoncelo ou cajón).Estrutura: Sem banda completa. Sem iluminação de grande porte (apenas luz cênica básica inclusa).Som: Sistema de som simplificado para ambientes fechados ou de pequeno porte.Duração: 1h30 de show.', '92265d77-2b62-4301-83e3-073949420cda'),
('531c2510-91da-4dbf-9d8c-e7555e0c1d7e', 'Pacote Standard (Intermediário)', 120, 900.00, 'O melhor custo-benefício para aniversários, formaturas e eventos corporativos de médio porte.Formato: Dupla + banda reduzida (violão, sanfona e percussão/bateria).Estrutura: Sem iluminação profissional de palco (inclusa apenas iluminação básica para os músicos).Som: Sistema de som completo para média cobertura (até 300 pessoas).Duração: 2h de show.', '92265d77-2b62-4301-83e3-073949420cda'),
('9b7ec718-36c7-4b25-a3ab-8dffb1df4be3', 'teste 1', 120, 500.00, 'ttttttt', 'c65498da-7bef-490f-8854-9a94412a670c'),
('9e601406-2360-4746-807d-1f4296a964a3', 'Show Especial de Casamentos', 240, 3000.00, 'Show especial para casamentos, maior duração, repertório adaptado, entrada dos noivos e outras adaptações', 'dd1fc02e-741c-42f6-8d63-764e8067d8c9'),
('a95d448d-9d27-4948-901a-92c6b64e5050', 'Pacote Premium (Show Completo)', 180, 1000.00, 'A experiência de festival ideal para grandes eventos, arenas, festas de peão ou casamentos de grande porte.Formato: Dupla + banda completa (violão, guitarra, baixo, bateria, sanfona e teclado).Estrutura: Com iluminação cenográfica e de palco profissional completa (Moving lights, painel de LED e efeitos visuais).Som: Sistema de som de alta potência (P.A. profissional) com equipe técnica dedicada (roadies e técnicos de som/luz).Duração: 2h15 de show + bis.', '92265d77-2b62-4301-83e3-073949420cda'),
('adf73677-7769-44b9-b234-bf0ee58d230d', 'Show teste', 120, 1800.00, 'Testando', 'c65498da-7bef-490f-8854-9a94412a670c'),
('d02bdfe4-0aab-46fc-9c18-5f28e403b789', 'Mais um', 120, 400.00, 'Mais um', 'c65498da-7bef-490f-8854-9a94412a670c');

